import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";
import { Switch } from "@/registry/erbium/ui/switch";
import { useState } from "react";

export default function SwitchForm() {
  const [submitted, setSubmitted] = useState<string>();

  return (
    <form
      className="flex w-72 flex-col gap-4"
      onSubmit={(event) => {
        event.preventDefault();
        const data = Object.fromEntries(new FormData(event.currentTarget));
        setSubmitted(JSON.stringify(data, null, 2));
      }}
    >
      <Field orientation="horizontal">
        <Switch name="newsletter" value="yes" uncheckedValue="no" />
        <FieldLabel>Subscribe to the newsletter</FieldLabel>
      </Field>
      <Field orientation="horizontal">
        <Switch name="terms" required />
        <FieldLabel>Accept the terms (required)</FieldLabel>
      </Field>
      <StatefulButton className="self-start" type="submit">
        Submit
      </StatefulButton>
      {submitted ? <pre className="rounded-md bg-muted p-3 text-xs">{submitted}</pre> : null}
    </form>
  );
}

import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Switch } from "@/registry/erbium/ui/switch";
import { HugeiconsIcon } from "@hugeicons/react";
import CheckIcon from "@hugeicons/core-free-icons/CheckIcon";
import MoonIcon from "@hugeicons/core-free-icons/MoonIcon";
import Sun01Icon from "@hugeicons/core-free-icons/Sun01Icon";
import XIcon from "@hugeicons/core-free-icons/XIcon";

export default function SwitchIcons() {
  return (
    <div className="flex flex-col gap-4">
      <Field orientation="horizontal">
        <Switch
          startIcon={<HugeiconsIcon icon={CheckIcon} />}
          endIcon={<HugeiconsIcon icon={XIcon} />}
          defaultChecked
        />
        <FieldLabel>Track icons</FieldLabel>
      </Field>
      <Field orientation="horizontal">
        <Switch thumbIcon={<HugeiconsIcon icon={Sun01Icon} />} />
        <FieldLabel>Thumb icon</FieldLabel>
      </Field>
      <Field orientation="horizontal">
        <Switch
          startIcon={<HugeiconsIcon icon={MoonIcon} />}
          endIcon={<HugeiconsIcon icon={Sun01Icon} />}
        />
        <FieldLabel>Dark mode</FieldLabel>
      </Field>
    </div>
  );
}

