const meta = {
  title: "UI/Switch",
  component: Switch,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "A control that allows the user to toggle between checked and not checked.\n\n**Import:** `@/registry/erbium/ui/switch`\n\n## Usage\n\n```tsx\nimport { Switch } from \"@/registry/erbium/ui/switch\";\n```\n\n```tsx\n<Switch />\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Switch](https://base-ui.com/react/components/switch)",
      },
    },
  },
} satisfies Meta<typeof Switch>;

export default { ...meta,  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

